def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'D'
    if n == 99:
        return 'D'

    opp_def = 0
    first_def = -1
    for i, (me, opp) in enumerate(history):
        if opp == 'D':
            opp_def += 1
            if first_def == -1:
                first_def = i

    if opp_def == 0:
        return 'D'
    if opp_def == n:
        return 'D'
    if n >= 10 and opp_def > n * 0.7:
        return 'D'
    if first_def != -1 and n - first_def <= 3:
        return 'C'

    last_me, last_opp = history[-1]
    if last_opp == 'D':
        return 'D'
    else:
        return 'C'
